/**
 * Synthetic SliQ-style export for the import rehearsal. NOTHING here is real: every name, number, amount and date is generated by this
 * file from a fixed seed (mulberry32) plus a hand-written list of awkward cases. The real SliQ export is never read, copied or imitated
 * beyond the provisional header guess in scripts/sliq-import/mappings/sliq.json.
 *
 * The scenario object is also the INDEPENDENT truth the tests check the database against: it holds the amounts in pence as generated,
 * not as the importer parsed them. Run twice with the same seed it gives byte-identical files.
 */
import { mkdirSync, writeFileSync } from "node:fs";
import path from "node:path";

export type SrcCustomer = { name: string; contact: string; email: string; phone: string; address: string; notes: string };
export type SrcLine = { doc: string; description: string; qty: string; unitP: number; netP: number | null; vatRate: number; vatP: number | null };
export type SrcInvoice = { number: string; customerRef: string; customerName: string | null; date: string; due: string; netP: number; vatP: number; grossP: number; status: string };
export type SrcPayment = { invoice: string; date: string; amountP: number; method: string; reference: string };
export type SrcQuote = { number: string; customerRef: string; date: string; grossP: number; status: string };
export type Scenario = {
  seed: number;
  customers: SrcCustomer[];
  invoices: SrcInvoice[];
  lines: SrcLine[];
  payments: SrcPayment[];
  quotes: SrcQuote[];
  /** The designed classification of the awkward cases, by invoice number. The tests assert the importer agrees with this, not the other way round. */
  facts: {
    duplicateInvoiceNumbers: string[];
    unknownCustomerInvoices: string[];
    gapInvoiceNumbers: string[];
    duplicateCustomerNames: string[][];
    paymentsToUnknownInvoice: string[];
    overpaid: string[];
    partPaid: string[];
    paidInFull: string[];
    unpaid: string[];
    duplicatePaymentInvoices: string[];
    headerLineMismatch: string[];
    withinRounding: string[];
    nonStandardNumbers: string[];
    /** Flagged by the importer as a possible discount (header net under the lines' net, or lines doubled by a duplicate number): its write guard refuses until each is excluded by number. */
    operatorExcluded: string[];
  };
};

const mulberry32 = (a: number) => () => {
  a |= 0;
  a = (a + 0x6d2b79f5) | 0;
  let t = Math.imul(a ^ (a >>> 15), 1 | a);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};

export const pounds = (p: number) => `${p < 0 ? "-" : ""}${Math.floor(Math.abs(p) / 100)}.${String(Math.abs(p) % 100).padStart(2, "0")}`;
const ddmmyyyy = (iso: string) => iso.split("-").reverse().join("/");
const addDays = (iso: string, n: number) => new Date(Date.parse(`${iso}T12:00:00Z`) + n * 86400000).toISOString().slice(0, 10);

export const DEFAULT_SEED = 20261106;

export function buildScenario(seed = DEFAULT_SEED): Scenario {
  const rnd = mulberry32(seed);
  const pick = <T,>(xs: T[]) => xs[Math.floor(rnd() * xs.length)];
  const int = (lo: number, hi: number) => lo + Math.floor(rnd() * (hi - lo + 1));

  const cust = (name: string, n: number): SrcCustomer => ({ name, contact: `Contact ${n}`, email: `accounts${n}@example.test`, phone: `0100 000 ${String(n).padStart(4, "0")}`, address: `${n} Test Street, Testville`, notes: "" });
  const named = [
    "Alpha Fabrications Ltd", "Beta Engineering Limited", "Smith & Sons Ltd", "Delta Steel (UK) Ltd", "Epsilon Welding", "Epsilon Welding Services",
    "Zeta Metals Ltd", "ZETA METALS LTD", "Theta Ltd", "Theta Holdings Ltd", "Omega Unused Ltd", "Acme Tools", "Acme Toolz",
  ];
  const customers = named.map((n, i) => cust(n, i + 1));
  const bulkNames: string[] = [];
  for (let i = 1; i <= 20; i++) {
    const n = `Bulk Customer ${String(i).padStart(2, "0")} Ltd`;
    bulkNames.push(n);
    customers.push(cust(n, 100 + i));
  }

  const invoices: SrcInvoice[] = [];
  const lines: SrcLine[] = [];
  const payments: SrcPayment[] = [];
  const quotes: SrcQuote[] = [];
  let day = 0;
  const nextDate = () => addDays("2026-01-02", day++ * 2); // 2, 4, 6 ... days: several days-of-month are above 12, so DD/MM vs MM/DD is not ambiguous

  /** One invoice with its lines. vatFromLine: Line VAT stated on each line (else left blank so the importer computes it at the rate). */
  function invoice(number: string, customerRef: string, customerName: string | null, spec: { desc: string; qty: string; unitP: number; rate: number }[], status: string, opts: { vatFromLine?: boolean; headerVatP?: number; headerGrossP?: number; headerNetP?: number } = {}) {
    const vatFromLine = opts.vatFromLine ?? true;
    let net = 0;
    let vat = 0;
    for (const s of spec) {
      const [i, f = ""] = s.qty.split(".");
      const milli = Number(i) * 1000 + Number(f.padEnd(3, "0"));
      const lineNet = (milli * s.unitP) / 1000;
      if (!Number.isInteger(lineNet)) throw new Error(`synthetic line ${number} is not an exact number of pence`);
      const lineVat = Math.round((lineNet * s.rate) / 100);
      net += lineNet;
      vat += lineVat;
      lines.push({ doc: number, description: s.desc, qty: s.qty, unitP: s.unitP, netP: lineNet, vatRate: s.rate, vatP: vatFromLine ? lineVat : null });
    }
    const date = nextDate();
    const hNet = opts.headerNetP ?? net;
    const hVat = opts.headerVatP ?? vat;
    invoices.push({ number, customerRef, customerName, date, due: addDays(date, 30), netP: hNet, vatP: hVat, grossP: opts.headerGrossP ?? hNet + hVat, status });
    return invoices.at(-1)!;
  }
  const pay = (invoiceNo: string, amountP: number, extra: Partial<SrcPayment> = {}) => {
    const inv = invoices.find((i) => i.number === invoiceNo);
    payments.push({ invoice: invoiceNo, date: extra.date ?? addDays(inv?.date ?? "2026-02-01", 9 + payments.length % 5), amountP, method: extra.method ?? "BACS", reference: extra.reference ?? `PAY-${payments.length + 1}` });
  };
  const one = (unitP: number, rate = 20, qty = "1") => [{ desc: "Fabricated bracket", qty, unitP, rate }];

  // ---- customer spelling variants (INV-0100..0113) ----
  invoice("INV-0100", "alpha fabrications ltd", "Alpha Fabrications Ltd", one(10000), "Paid");
  invoice("INV-0101", "  Alpha   Fabrications   LIMITED ", "Alpha Fabrications Ltd", one(25000), "Unpaid");
  invoice("INV-0102", "BETA ENGINEERING LTD", "Beta Engineering Limited", one(40000), "Unpaid");
  invoice("INV-0103", "Smith and Sons Limited", "Smith & Sons Ltd", one(12000), "Unpaid");
  invoice("INV-0104", "SMITH & SONS LTD", "Smith & Sons Ltd", one(8000), "Unpaid");
  // INV-0105 is not in the export at all: a gap in SliQ's own sequence.
  invoice("INV-0106", "Delta Steel UK Ltd", "Delta Steel (UK) Ltd", one(30000), "Unpaid");
  invoice("INV-0107", "Epsilon Welding", "Epsilon Welding", one(5000), "Unpaid");
  invoice("INV-0108", "Epsilon Welding Services", "Epsilon Welding Services", one(7000), "Unpaid");
  invoice("INV-0109", "Theta Ltd", "Theta Ltd", one(6000), "Unpaid");
  invoice("INV-0112", "Theta Holdings Ltd", "Theta Holdings Ltd", one(9000), "Unpaid");
  invoice("INV-0113", "Zeta Metals Ltd", "Zeta Metals Ltd", one(11000), "Unpaid"); // two customer records normalise alike: resolves to the first
  invoice("INV-0114", "Acme Toolz", "Acme Toolz", one(1500), "Unpaid");
  // INV-0110 is listed twice by SliQ (two different customers), INV-0111 names a customer that is not in the customers file.
  invoice("INV-0110", "Beta Engineering Limited", null, one(10000), "Unpaid");
  invoice("INV-0110", "Alpha Fabrications Ltd", null, one(20000), "Unpaid");
  invoice("INV-0111", "Nonexistent Fabrications Ltd", null, one(3000), "Unpaid");

  // ---- totals (INV-0120..0126) ----
  invoice("INV-0120", "Alpha Fabrications Ltd", "Alpha Fabrications Ltd", one(1240, 20, "2.5"), "Unpaid"); // 2.5 x 12.40 = 31.00, VAT 6.20
  invoice("INV-0121", "Beta Engineering Limited", "Beta Engineering Limited", [{ desc: "Standard", qty: "1", unitP: 10000, rate: 20 }, { desc: "Reduced", qty: "1", unitP: 5000, rate: 5 }, { desc: "Zero", qty: "1", unitP: 2500, rate: 0 }], "Unpaid");
  // Three lines of 0.99 at 20%, line VAT left blank: computed 0.20 a line (0.60) against a header VAT of 0.59 (VAT on the 2.97 total): a penny of rounding.
  invoice("INV-0122", "Theta Ltd", "Theta Ltd", [1, 2, 3].map((n) => ({ desc: `Washer ${n}`, qty: "1", unitP: 99, rate: 20 })), "Unpaid", { vatFromLine: false, headerVatP: 59 });
  invoice("INV-0123", "Delta Steel (UK) Ltd", "Delta Steel (UK) Ltd", one(10000), "Unpaid", { headerGrossP: 12001 }); // header net + VAT is 120.00 but gross says 120.01
  invoice("INV-0124", "Zeta Metals Ltd", "Zeta Metals Ltd", one(10000), "Unpaid", { headerNetP: 9900, headerGrossP: 11900 }); // header net 99.00 against lines 100.00
  invoice("INV-0125", "Smith & Sons Ltd", "Smith & Sons Ltd", one(2999, 20, "3"), "Unpaid"); // 3 x 29.99 = 89.97
  invoice("INV-0126", "Acme Tools", "Acme Tools", one(3334, 20, "0.5"), "Unpaid"); // 0.5 x 33.34 = 16.67

  // ---- payments (INV-0130..0139) ----
  invoice("INV-0130", "Alpha Fabrications Ltd", "Alpha Fabrications Ltd", one(10000), "Paid");
  pay("INV-0130", 12000);
  invoice("INV-0131", "Beta Engineering Limited", "Beta Engineering Limited", one(50000), "Part Paid"); // gross 600.00
  pay("INV-0131", 20000);
  pay("INV-0131", 15000);
  invoice("INV-0132", "Smith & Sons Ltd", "Smith & Sons Ltd", one(25000), "Paid"); // gross 300.00 in three
  pay("INV-0132", 10000);
  pay("INV-0132", 10000);
  pay("INV-0132", 10000);
  invoice("INV-0133", "Delta Steel (UK) Ltd", "Delta Steel (UK) Ltd", one(10000), "Paid"); // gross 120.00, 130.00 received
  pay("INV-0133", 13000);
  invoice("INV-0134", "Theta Ltd", "Theta Ltd", one(10000), "Unpaid");
  invoice("INV-0135", "Zeta Metals Ltd", "Zeta Metals Ltd", one(10000), "Paid");
  pay("INV-0135", 6000, { date: "2026-03-05", reference: "SAME" });
  pay("INV-0135", 6000, { date: "2026-03-05", reference: "SAME" }); // the same receipt listed twice
  invoice("INV-0136", "Acme Tools", "Acme Tools", one(10000), "Unpaid");
  pay("INV-0136", 0);
  invoice("INV-0137", "Epsilon Welding", "Epsilon Welding", one(10000), "Paid");
  payments.push({ invoice: "INV-0137", date: "", amountP: 12000, method: "BACS", reference: "NODATE" });
  invoice("INV-0138", "Theta Holdings Ltd", "Theta Holdings Ltd", one(10000), "Draft");
  pay("INV-0138", 5000);
  invoice("INV-0139", "Epsilon Welding Services", "Epsilon Welding Services", one(10000), "Void");
  pay("INV-0999", 7777, { date: "2026-04-01", reference: "ORPHAN" }); // a receipt for an invoice that is not in the export

  // ---- numbering oddities ----
  invoice("INV-0200", "Alpha Fabrications Ltd", "Alpha Fabrications Ltd", one(1000), "Unpaid"); // a high number: the company's counter must start after it
  invoice("SI/2026/0007", "Alpha Fabrications Ltd", "Alpha Fabrications Ltd", one(1000), "Unpaid"); // a number in another style: kept verbatim
  invoice("00045", "Beta Engineering Limited", "Beta Engineering Limited", one(1000), "Unpaid"); // leading zeros, no prefix: kept verbatim

  // ---- quotes ----
  for (const [n, c, g, s] of [["QUO-0050", "Alpha Fabrications Ltd", 36000, "Sent"], ["QUO-0051", "Beta Engineering Limited", 48000, "Accepted"], ["QUO-0053", "Theta Ltd", 12000, "Draft"]] as const) {
    quotes.push({ number: n, customerRef: c, date: nextDate(), grossP: g, status: s });
  }

  // ---- seeded bulk: INV-0300.. consecutive, no gaps ----
  for (let i = 0; i < 40; i++) {
    const number = `INV-${String(300 + i).padStart(4, "0")}`;
    const name = pick(bulkNames);
    const spec = Array.from({ length: int(1, 4) }, (_, k) => ({ desc: `Part ${k + 1} for ${number}`, qty: String(int(1, 9)), unitP: int(5, 4000) * 5, rate: pick([20, 20, 20, 5, 0]) }));
    const inv = invoice(number, name, name, spec, "Unpaid");
    const pattern = pick(["full", "full", "part", "none", "split"]);
    if (pattern === "full") pay(number, inv.grossP);
    else if (pattern === "part") pay(number, Math.floor(inv.grossP / 2));
    else if (pattern === "split") {
      const first = Math.floor(inv.grossP / 3);
      pay(number, first);
      pay(number, inv.grossP - first);
    }
  }

  return {
    seed,
    customers,
    invoices,
    lines,
    payments,
    quotes,
    facts: {
      duplicateInvoiceNumbers: ["INV-0110"],
      unknownCustomerInvoices: ["INV-0111"],
      gapInvoiceNumbers: ["INV-0105"],
      duplicateCustomerNames: [["Zeta Metals Ltd", "ZETA METALS LTD"]],
      paymentsToUnknownInvoice: ["INV-0999"],
      overpaid: ["INV-0133"],
      partPaid: ["INV-0131"],
      paidInFull: ["INV-0130", "INV-0132"],
      unpaid: ["INV-0134"],
      duplicatePaymentInvoices: ["INV-0135"],
      headerLineMismatch: ["INV-0123", "INV-0124"],
      withinRounding: ["INV-0122"],
      nonStandardNumbers: ["SI/2026/0007", "00045"],
      operatorExcluded: ["INV-0110", "INV-0124"],
    },
  };
}

const q = (v: string | number) => {
  const s = String(v);
  return /[",\n]/.test(s) ? `"${s.replaceAll('"', '""')}"` : s;
};
const csv = (rows: (string | number)[][]) => `${rows.map((r) => r.map(q).join(",")).join("\r\n")}\r\n`;

/** Writes the export folder (the provisional SliQ headers plus Line Net / Line VAT, see rehearsal-mapping.json) and returns its path. */
export function writeExport(dir: string, s: Scenario): string {
  mkdirSync(dir, { recursive: true });
  const w = (file: string, rows: (string | number)[][]) => writeFileSync(path.join(dir, file), csv(rows));
  w("customers.csv", [["Company Name", "Contact Name", "Email Address", "Phone Number", "Address", "Notes"], ...s.customers.map((c) => [c.name, c.contact, c.email, c.phone, c.address, c.notes])]);
  w("invoices.csv", [["Number", "Customer", "Invoice Date", "Due Date", "Net", "VAT", "Gross", "Status", "Discount"], ...s.invoices.map((i) => [i.number, i.customerRef, ddmmyyyy(i.date), ddmmyyyy(i.due), pounds(i.netP), pounds(i.vatP), pounds(i.grossP), i.status, ""])]);
  w("invoice-lines.csv", [["Document Number", "Description", "Quantity", "Unit Price", "Line Net", "VAT Rate", "Line VAT", "Discount"], ...s.lines.map((l) => [l.doc, l.description, l.qty, pounds(l.unitP), l.netP === null ? "" : pounds(l.netP), l.vatRate, l.vatP === null ? "" : pounds(l.vatP), ""])]);
  w("payments.csv", [["Invoice Number", "Date", "Amount", "Method", "Reference"], ...s.payments.map((p) => [p.invoice, p.date ? ddmmyyyy(p.date) : "", pounds(p.amountP), p.method, p.reference])]);
  w("quotes.csv", [["Number", "Customer", "Quote Date", "Gross", "Status", "Discount"], ...s.quotes.map((x) => [x.number, x.customerRef, ddmmyyyy(x.date), pounds(x.grossP), x.status, ""])]);
  return dir;
}
